update ${tn}
set del_flag = 1, valid = 0
where version = #{version}

mapper.select:
SELECT t.valid
FROM ${tableName} AS t
WHERE t.id = #{businessId}

select version
from ${tableName}
where del_flag = '0' and version <= #{version}
group by version
order by version desc
limit 1

select version
from ${tableName}
where del_flag = '0' and version <= #{version}
and type = #{type}
group by version
order by version desc
limit 1
